class Solution {
    public int countHillValley(int[] nums){
        List<Integer> values=new ArrayList<>();
        for(int value:nums)if(values.isEmpty()||values.get(values.size()-1)!=value)values.add(value);
        int answer=0;
        for(int i=1;i+1<values.size();i++)if(values.get(i)>values.get(i-1)&&values.get(i)>values.get(i+1)||values.get(i)<values.get(i-1)&&values.get(i)<values.get(i+1))answer++;
        return answer;
    }
}

code.kotlin:
class Solution {
    fun countHillValley(nums:IntArray):Int{
        val values=mutableListOf<Int>();
        for(value in nums)if(values.isEmpty()||values.last()!=value)values.add(value);
        var answer=0;
        for(i in 1 until values.lastIndex)if(values[i]>values[i-1]&&values[i]>values[i+1]||values[i]<values[i-1]&&values[i]<values[i+1])answer++;
        return answer
    }
}

